(window.GioKinhBooks=window.GioKinhBooks||{})["a-di-da"]={"id":"a-di-da","title":"Kinh A Di Đà","by":"Nghi thức tụng niệm · Phần dịch nghĩa, dịch âm và tiếng Anh","src":"https://www.daotranglienhoa.com/wp-content/uploads/2022/01/kinh_a_di_da_am_nghia.pdf","srcName":"Đạo Tràng Liên Hoa","chapters":[{"t":"Kinh A Di Đà","b":[["v",["NIỆM HƯƠNG","(Thắp đèn đốt hương trầm xong, đứng ngay ngắn chắp tay"]],["v",["để ngang ngực mật niệm.)","TỊNH PHÁP GIỚI CHƠN NGÔN","Án lam tóa ha. (3 lần)","TỊNH TAM NGHIỆP CHƠN NGÔN"]],["v",["Án ta phạ bà phạ, thuật đà ta phạ, đạt mạ","ta phạ, bà phạ thuật độ hám. (3 lần)"]],["p","(Chủ lễ thắp ba cây hương quỳ ngay thẳng cầm hương"],["p","ngang trán niệm bài cúng hương.)"]]},{"t":"Nguyện Hương","b":[["v",["Nguyện đem lòng thành kính,","Gởi theo đám mây hương,","Phưởng phất khắp mười phương,","Cúng dường ngôi Tam Bảo.","Thề trọn đời giữ đạo,","Theo tự tánh làm lành,","Cùng Pháp giới chúng sanh,","Cầu Phật từ gia hộ.","Tâm Bồ Đề kiên cố,","Chí tu học vững bền,","Xa bể khổ nguồn mê,","Chóng quay về bờ giác."]]],"p":"Phần Dịch Nghĩa"},{"t":"Tán Phật","b":[["v",["Đấng Pháp Vương vô thượng,","Ba cõi chẳng ai bằng,","Thầy dạy khắp trời người,","Cha lành chung bốn loài.","Quy y tròn một niệm,","Dứt sạch nghiệp ba kỳ,","Xưng dương cùng tán thán,","Ức kiếp không cùng tận."]]],"p":"Phần Dịch Nghĩa"},{"t":"Quán Tưởng","b":[["p","Phật, chúng sanh, tánh thường rỗng lặng, Đạo cảm thông không thể nghĩ bàn."],["p","Lưới đế châu ví đạo tràng,"],["p","Mười phương Phật bảo, hào quang sáng"],["v",["ngời.","Trước bảo tọa thân con ảnh hiện,","Cúi đầu xin thệ nguyện quy y."]]],"p":"Phần Dịch Nghĩa"},{"t":"Đảnh Lễ","b":[["p","Chí tâm đảnh lễ: Nam mô tận hư không, biến pháp giới, quá, hiện, vị lai thập phương chư Phật, Tôn Pháp, Hiền Thánh Tăng, Thường Trú Tam Bảo. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Ta Bà Giáo Chủ Bổn Sư Thích Ca Mâu Ni Phật, Đương Lai Hạ Sanh Di Lặc Tôn Phật, Đại Trí Văn Thù Sư Lợi Bồ Tát, Đại Hạnh Phổ Hiền Bồ Tát, Hộ Pháp Chư Tôn Bồ Tát, Linh Sơn Hội Thượng Phật Bồ Tát. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Tây Phương Cực Lạc Thế Giới Đại Từ Đại Bi A Di Đà Phật, Đại Bi Quán Thế Âm Bồ Tát, Đại Thế Chí Bồ Tát, Đại Nguyện Địa Tạng Vương Bồ Tát, Thanh Tịnh Đại Hải Chúng Bồ Tát. (1 lạy)"]],"p":"Phần Dịch Nghĩa"},{"t":"Tán Lư Hương","b":[["v",["Kim lư vừa bén chiên đàn,","Khắp xông pháp giới đạo tràng mười"]],["v",["phương, Hiện thành mây báu kiết tường,","Chư Phật rõ biết ngọn hương chí thiền,","Pháp thân toàn thể hiện tiền,","Chứng minh hương nguyện phước liền","ban cho.","Nam mô Hương Vân Cái Bồ Tát. (3 lần)"]]],"p":"Phần Dịch Nghĩa"},{"t":"Chú Đại Bi","b":[["v",["Nam mô Đại Bi Hội Thượng Phật Bồ Tát. (3 lần)","Thiên thủ thiên nhãn vô ngại đại bi tâm đà la ni.","Nam mô hắc ra đát na, đa ra dạ da."]],["p","Nam mô a rị da, bà lô yết đế, thước bát ra da, Bồ đề tát đỏa bà da, ma ha tát đỏa bà da, ma ha ca lô ni ca da. Án, tát bàn ra phạt duệ số đát na đát tỏa."],["p","Nam mô tất kiết lật đỏa y mông a rị da, bà lô kiết đế thất Phật ra lăng đà bà."],["p","Nam mô na ra cẩn trì hê rị, ma ha bàn đa sa mế, tát bà a tha đậu du bằng, a thệ dựng, tát bà tát đa, na ma bà già, ma phạt đạt đậu, đát điệt tha. Án a bà lô hê, lô ca đế, ca ra đế, di hê rị, ma ha bồ đề tát đỏa, tát bà tát bà, ma ra ma ra, ma hê ma hê, rị đà dựng, câu lô câu lô kiết mông, độ lô độ lô, phạt xà da đế, ma ha phạt xà da đế, đà ra đà ra, địa rị ni, thất Phật ra da, dá ra dá ra. Mạ mạ phạt ma ra, mục đế lệ, y hê y hê, thất na thất na a ra sâm Phật ra xá lợi, phạt sa phạt sâm, Phật ra xá da, hô lô hô lô ma ra, hô lô hô lô hê rị, ta ra ta ra, tất rị tất rị, tô rô tô rô, bồ đề dạ bồ đề dạ, bồ đà dạ, bồ đà dạ, di đế rị dạ, na ra cẩn trì địa rị sắc ni na, ba dạ ma na ta bà ha."],["p","Tất đà dạ ta bà ha. Ma ha tất đà dạ ta bà ha. Tất đà du nghệ thất bàn ra dạ ta bà ha."],["p","Na ra cẩn trì ta bà ha. Ma ra na ra ta bà ha. Tất ra tăng a mục khê da, ta bà ha. Ta bà ma ha, a tất đà dạ, ta bà ha. Giả kiết ra a tất đà dạ, ta bà ha. Ba đà ma yết tất đà dạ, ta bà ha. Na ra cẩn trì bàn đà ra dạ, ta bà ha. Ma bà lị thắng yết ra dạ, ta bà ha."],["v",["Nam mô hắc ra đát na, đa ra dạ da.","Nam mô a rị da, bà lô yết đế thước bàng ra dạ, ta bà ha.","Án tất điện đô, mạn đa ra, bạt đà dạ, ta bà ha. (3 lần)"]]],"p":"Phần Dịch Nghĩa"},{"t":"Phát Nguyện Trì Kinh","b":[["p","Nam Mô Thập Phương Thường Trụ Tam"],["p","Bảo. (3 lần)"],["v",["Lạy đấng Tam Giới Tôn","Quy mạng mười phương Phật","Nay con phát nguyện rộng","Trì tụng Kinh Di Đà","Trên đền bốn ơn nặng","Dưới cứu khổ tam đồ","Nếu có ai thấy nghe","Đều phát tâm Bồ Đề,","Khi mãn báo thân này","Sanh qua cõi Cực Lạc"]],["p","Nam Mô Bổn Sư Thích Ca Mâu Ni Phật. (3 lần)"]],"p":"Phần Dịch Nghĩa"},{"t":"Khai Kinh","b":[["v",["Phật Pháp rộng sâu rất nhiệm mầu","Trăm ngàn muôn kiếp khó tìm cầu","Nay con nghe thấy chuyên trì tụng","Nguyện tỏ Như Lai nghĩa nhiệm mầu"]],["p","Nam Mô Liên Trì Hải Hội Phật Bồ Tát. (3 lần)"]],"p":"Phần Dịch Nghĩa"},{"t":"Phật Nói Kinh A Di Đà","b":[["p","(HT Thích Trí Tịnh Việt dịch.)"],["p","Ta nghe như vầy: Một thuở nọ Đức Phật ở nơi vườn Kỳ Thọ, Cấp Cô Độc nước Xá Vệ, cùng với một nghìn hai trăm năm mươi vị đại Tỳ kheo câu hội, đều là bậc A La Hán mọi người đều quen biết, như là:"],["p","Trưởng lão Xá Lợi Phất, Đại Mục Kiền Liên, Đại Ca Diếp, Ma Ha Ca Chiên Diên, Ma Ha Câu Hy La, Ly Bà Đa, Châu Lợi Bàn Đà Già, Nan Đà, A Nan Đà, La Hầu La, Kiều Phạm Ba Đề, Tân Đầu Lư Phả La Đọa, Ca Lưu Đà Di, Ma Ha Kiếp Tân Na, Bạc Câu La, A Nậu Lâu Đà, những vị đại đệ tử như thế."],["p","Và hàng Đại Bồ Tát, Văn Thù Sư Lợi, Pháp Vương Tử, A Dật Đa Bồ Tát, Càn Đà Ha Đề Bồ Tát, Thường Tinh Tấn Bồ Tát."],["p","Cùng với các vị Đại Bồ Tát như thế và với vô lượng chư Thiên như ông Thích Đề Hoàn Nhơn v.v... đại chúng cùng đến dự hội."],["p","Bấy giờ đức Phật bảo ngài Trưởng Lão Xá Lợi Phất rằng: Từ đây qua Phương Tây quá mười muôn ức cõi Phật, có thế giới tên là Cực Lạc, trong thế giới đó có đức Phật hiệu là A Di Đà hiện nay đương nói pháp."],["p","Xá Lợi Phất! Cõi đó vì sao tên là Cực Lạc? Vì chúng sanh trong cõi đó không có bị những sự khổ, chỉ hưởng những điều vui, nên nước đó tên là Cực Lạc."],["p","Xá Lợi Phất! Lại trong cõi Cực Lạc có bảy từng bao lơn, bảy từng mành lưới, bảy từng hàng cây, đều bằng bốn chất báu bao bọc giáp vòng, vì thế nên nước đó tên là Cực Lạc."],["p","Xá Lợi Phất! Lại trong cõi Cực Lạc có ao bằng bảy chất báu, trong ao đầy dẫy nước đủ tám công đức, đáy ao thuần dùng cát vàng trải làm đất. Vàng bạc, lưu ly, pha lê hiệp thành những thềm, đường ở bốn bên ao, trên thềm đường có lầu gác cũng đều nghiêm sức bằng vàng, bạc, lưu ly, pha lê, xa cừ, xích châu, mã não. Trong ao có hoa sen lớn như bánh xe, hoa sắc xanh thời ánh sáng xanh, sắc vàng thời ánh sáng vàng, sắc đỏ thời ánh sáng đỏ, sắc trắng thời ánh sáng trắng, mầu nhiệm thơm tho trong sạch."],["p","Xá Lợi Phất! Cõi nước Cực Lạc thành tựu công đức trang nghiêm dường ấy."],["p","Xá Lợi Phất! Lại trong cõi nước của đức Phật đó, thường trổi nhạc trời, đất bằng vàng ròng, ngày đêm sáu thời rưới hoa trời mạn đà la. Chúng sanh trong cõi đó thường vào lúc sáng sớm, đều lấy đãy hoa đựng những hoa tốt đem cúng dường mười muôn ức đức Phật ở phương khác, đến giờ ăn liền trở về bổn quốc ăn cơm xong đi kinh hành."],["p","Xá Lợi Phất! Cõi nước Cực Lạc thành tựu công đức trang nghiêm dường ấy."],["p","Lại nữa, Xá Lợi Phất! Cõi đó thường có những giống chim mầu sắc xinh đẹp lạ thường, nào chim Bạch hạt, Khổng tước, Anh võ, Xá lợi, Ca lăng tần già, Cọng mạng, những giống chim đó ngày đêm sáu thời kêu tiếng hòa nhã. Tiếng chim đó diễn nói những pháp như Ngũ Căn, Ngũ Lực, Thất Bồ Đề Phần, Bát Thánh Đạo Phần v.v… Chúng sanh trong cõi đó nghe tiếng chim xong thảy đều niệm Phật, niệm Pháp, niệm Tăng."],["p","Xá Lợi Phất! Ông chớ cho rằng những giống chim đó thiệt là do tội báo sanh ra. Vì sao? Vì cõi của đức Phật đó không có ba đường dữ."],["p","Xá Lợi Phất! Cõi của đức Phật đó tên đường dữ còn không có huống gì lại có sự thật. Những giống chim đó là do đức Phật A Di Đà muốn làm cho tiếng pháp được tuyên lưu mà biến hóa làm ra đấy thôi."],["p","Xá Lợi Phất! Trong cõi nước của đức Phật đó, gió nhẹ thổi động các hàng cây báu và động mành lưới báu, làm vang ra tiếng vi diệu, thí như trăm nghìn thứ nhạc đồng một lúc hòa chung. Người nào nghe tiếng đó tự nhiên đều sanh lòng niệm Phật, niệm Pháp, niệm Tăng."],["p","Xá Lợi Phất! Cõi nước của đức Phật đó thành tựu công đức trang nghiêm dường ấy."],["p","Xá Lợi Phất! Nơi ý ông nghĩ sao? Đức Phật đó vì sao hiệu là A Di Đà?"],["p","Xá Lợi Phất! Đức Phật đó, hào quang sáng chói vô lượng, soi suốt các cõi nước trong mười phương không bị chướng ngại vì thế nên hiệu là A Di Đà."],["p","Xá Lợi Phất! Đức Phật đó và nhân dân của Ngài sống lâu vô lượng vô biên a tăng kỳ kiếp, nên hiệu là A Di Đà."],["p","Xá Lợi Phất! Đức Phật A Di Đà thành Phật nhẫn lại đến nay, đã được mười kiếp."],["p","Xá Lợi Phất! Lại đức Phật đó có vô lượng vô biên Thanh Văn đệ tử đều là bậc A La Hán, chẳng phải tính đếm mà có thể biết được, hàng Bồ Tát chúng cũng đông như thế."],["p","Xá Lợi Phất! Cõi nước của đức Phật đó thành tựu công đức trang nghiêm dường ấy."],["p","Xá Lợi Phất! Lại trong cõi Cực Lạc, những chúng sanh vãng sanh vào đó đều là bậc bất thối chuyển. Trong đó có rất nhiều vị bậc nhất sanh bổ xứ, số đó rất đông, chẳng phải tính đếm mà biết được, chỉ có thể dùng số vô lượng vô biên a tăng kỳ để nói thôi."],["p","Xá Lợi Phất! Chúng sanh nào nghe những điều trên đây, nên phải phát nguyện cầu sanh về nước đó. Vì sao? Vì đặng cùng với các bậc Thượng thiện nhơn như thế câu hội một chỗ."],["p","Xá Lợi Phất! Chẳng có thể dùng chút ít thiện căn phước đức nhơn duyên mà được sanh về cõi đó."],["p","Xá Lợi Phất! Nếu có thiện nam tử, thiện nữ nhân nào nghe nói đức Phật A Di Đà, rồi chấp trì danh hiệu của đức Phật đó, hoặc trong một ngày, hoặc hai ngày, hoặc ba ngày, hoặc bốn ngày, hoặc năm ngày, hoặc sáu ngày, hoặc bảy ngày, một lòng không tạp loạn."],["p","Thời người đó đến lúc lâm chung đức Phật A Di Đà cùng hàng Thánh Chúng hiện thân ở trước người đó."],["p","Người đó lúc chết tâm thần không điên đảo, liền được vãng sanh về cõi nước Cực Lạc của đức Phật A Di Đà."],["p","Xá Lợi Phất! Ta thấy có sự lợi ích ấy nên nói những lời như thế. Nếu có chúng sinh nào, nghe những lời trên đó, nên phải phát nguyện sanh về cõi nước Cực Lạc."],["p","Xá Lợi Phất! Như Ta hôm nay ngợi khen công đức lợi ích chẳng thể nghĩ bàn của đức Phật A Di Đà, phương Đông cũng có đức A Súc Bệ Phật, Tu Di Tướng Phật, Đại Tu Di Phật, Tu Di Quang Phật, Diệu Âm Phật, Hằng hà sa số những đức Phật như thế đều tại nước mình, hiện ra tướng lưỡi rộng dài trùm khắp cõi tam thiên đại thiên mà nói lời thành thật rằng: “Chúng sanh các ngươi phải nên tin Kinh: Xưng Tán Bất Khả Tư Nghị Công Đức Nhất Thiết Chư Phật Sở Hộ Niệm Này.”"],["p","Xá Lợi Phất! Thế giới phương Nam, có đức Nhật Nguyệt Đăng Phật, Danh Văn Quang Phật, Đại Diệm Kiên Phật, Tu Di Đăng Phật, Vô Lượng Tinh Tấn Phật."],["p","Hằng hà sa số những đức Phật như thế, đều tại nước mình, hiện ra tướng lưỡi rộng dài trùm khắp cõi tam thiên đại thiên mà nói lời thành thật rằng: “Chúng sanh các ngươi phải nên tin Kinh: Xưng Tán Bất Khả Tư Nghị Công Đức Nhất Thiết Chư Phật Sở Hộ Niệm Này.”"],["p","Xá Lợi Phất! Thế giới phương Tây, có đức Vô Lượng Thọ Phật, Vô Lượng Tướng Phật, Vô Lượng Tràng Phật, Đại Quang Phật, Đại Minh Phật, Bửu Tướng Phật, Tịnh Quang Phật. Hằng hà sa số những đức Phật như thế, đều tại nước mình, hiện ra tướng lưỡi rộng dài trùm khắp cõi tam thiên đại thiên mà nói lời thành thật rằng: “Chúng sanh các ngươi phải nên tin Kinh: Xưng Tán Bất Khả Tư Nghị Công Đức Nhất Thiết Chư Phật Sở Hộ Niệm Này.”"],["p","Xá Lợi Phất! Thế giới phương Bắc, có đức Diệm Kiên Phật, Tối Thắng Âm Phật, Nan Trở Phật, Nhựt Sanh Phật, Võng Minh Phật. Hằng hà sa số những đức Phật như thế, đều tại nước mình, hiện ra tướng lưỡi rộng dài trùm khắp cõi tam thiên đại thiên mà nói lời thành thật rằng: “Chúng sanh các ngươi phải nên tin Kinh: Xưng Tán Bất Khả Tư Nghị Công Đức Nhất Thiết Chư Phật Sở Hộ Niệm Này.”"],["p","Xá Lợi Phất! Thế giới phương dưới, có đức Sư Tử Phật, Danh Văn Phật, Danh Quang Phật, Đạt Mạ Phật, Pháp Tràng Phật, Trì Pháp Phật. Hằng hà sa số những đức Phật như thế, đều tại nước mình, hiện ra tướng lưỡi rộng dài trùm khắp cõi tam thiên đại thiên mà nói lời thành thật rằng: “Chúng sanh các ngươi phải nên tin Kinh: Xưng Tán Bất Khả Tư Nghị Công Đức Nhất Thiết Chư Phật Sở Hộ Niệm Này.”"],["p","Xá Lợi Phất! Thế giới phương trên, Có đức Phạm Âm Phật, Tú Vương Phật, Hương Thượng Phật, Hương Quang Phật, Đại Diệm Kiên Phật, Tạp Sắc Bửu Hoa Nghiêm Thân Phật, Ta La Thọ Vương Phật, Bửu Hoa Đức Phật, Kiến Nhất Thiết Nghĩa Phật, Như Tu Di Sơn Phật. Hằng hà sa số những đức Phật như thế, đều tại nước mình, hiện ra tướng lưỡi rộng dài trùm khắp cõi tam thiên đại thiên mà nói lời thành thật rằng: “Chúng sanh các ngươi phải nên tin Kinh: Xưng Tán Bất Khả Tư Nghị Công Đức Nhất Thiết Chư Phật Sở Hộ Niệm Này.”"],["p","Xá Lợi Phất! Nơi ý của ông nghĩ thế nào, vì sao tên là Kinh: Nhất Thiết Chư Phật Sở Hộ Niệm?"],["p","Xá Lợi Phất! Vì nếu có thiện nam tử, thiện nữ nhân nào nghe kinh này mà thọ trì đó, và nghe danh hiệu của đức Phật, thời những thiện nam tử cùng thiện nữ nhân ấy đều được tất cả các đức Phật hộ niệm, đều được không thối chuyển nơi đạo Vô Thượng Chánh Đẳng Chánh Giác."],["p","Xá Lợi Phất! Cho nên các ông đều phải tin nhận lời của Ta và của các đức Phật nói."],["p","Xá Lợi Phất! Nếu có người đã phát nguyện, hiện nay phát nguyện, sẽ phát nguyện muốn sanh về cõi nước của đức Phật A Di Đà, thời những người ấy đều đặng không thối chuyển nơi đạo Vô Thượng Chánh Đẳng Chánh Giác, nơi cõi nước kia, hoặc đã sanh về rồi, hoặc hiện nay sanh về, hoặc sẽ sanh về."],["p","Xá Lợi Phất! Cho nên các thiện nam tử thiện nữ nhân nếu người nào có lòng tin thời phải nên phát nguyện sanh về cõi nước kia."],["p","Xá Lợi Phất! Như ta hôm nay ngợi khen công đức chẳng thể nghĩ bàn của các đức Phật, các đức Phật đó cũng ngợi khen công đức chẳng thể nghĩ bàn của Ta mà nói lời nầy: “Đức Thích Ca Mâu Ni Phật hay làm được việc rất khó khăn hi hữu, có thể ở trong cõi Ta Bà đời ác năm món trược: kiếp trược, kiến trược, phiền não trược, chúng sanh trược, mạng trược, mà Ngài chứng được ngôi Vô Thượng Chánh Đẳng Chánh Giác, Ngài vì các chúng sanh nói kinh pháp mà tất cả thế gian khó tin này”."],["p","Xá Lợi Phất! Phải biết rằng Ta ở trong đời ác ngũ trược thật hành việc khó này: đặng thành bậc Vô Thượng Chánh Giác và vì tất cả thế gian nói kinh pháp khó tin này, đó là rất khó."],["p","Đức Phật nói kinh này rồi, Ngài Xá Lợi Phất cùng các vị Tỳ kheo, tất cả trong đời: Trời, Người, A Tu La, v.v... nghe lời của đức Phật dạy, đều vui mừng tin nhận đảnh lễ mà lui ra."]],"p":"Phần Dịch Nghĩa"},{"t":"Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh","b":[["p","Khi Ngài Quán Tự Tại Bồ Tát thực hành sâu xa Pháp Bát Nhã Ba La Mật Đa, Ngài soi thấy năm uẩn đều không, qua hết thảy khổ ách."],["p","Này ông Xá Lợi Phất, sắc chăn̉ g khác không, không chăn̉ g khác sắc, sắc tức là không, không tức là sắc. Thọ, Tưởng, Hành, Thức cũng đều như thế."],["p","Này ông Xá Lợi Phất, tướng không của mọi pháp không sanh, không diệt, không dơ, không sạch, không thêm, không bớt, nên trong chân không, không có sắc, không có thọ, tưởng, hành, thức, không có mắt, tai, mũi, lưỡi, thân, ý, không có sắc, thinh, hương, vị, xúc, pháp, không có nhãn giới, cho đến không có ý thức giới, không có vô minh, cũng không có cái hết vô minh, cho đến không có già chết, cũng không có cái hết già chết, không có khổ, tập, diệt, đạo, không có trí huệ, cũng không có chứng đắc. Vì không có chỗ chứng đắc, nên Bồ Tát y theo Bát Nhã Ba La Mật Đa, tâm không ngăn ngại."],["p","Vì không ngăn ngại, nên không sợ hãi, xa hăn̉ điên đảo, mộng tưởng, đạt tới cứu cánh Niết Bàn. Chư Phật trong ba đời cũng y theo Bát Nhã Ba La Mật Đa, được đạo quả vô thượng chánh đăn̉ g chánh giác. Nên biết Bát Nhã Ba La Mật Đa là Đại Thần chú, là Đại Minh chú, là Vô Thượng chú, là Vô Đăn̉ g Đăn̉ g chú, trừ được hết thảy khổ, chân thật không hư."],["p","Vì vậy, liền nói chú Bát Nhã Ba La Mật Đa:"],["p","“Yết đế yết đế, ba la yết đế, ba la tăng yết đế, bồ đề tát bà ha.” (3 lần)"]],"p":"Phần Dịch Nghĩa"},{"t":"Vãng Sanh Quyết Định Chơn Ngôn","b":[["p","Nam mô a di đa bà dạ, đa tha già đa dạ, đa địa dạ tha. A di rị đô bà tỳ, a di rị đa tất đam bà tỳ, a di rị đa tỳ ca lan đế, a di rị đa tỳ ca lan đa, dà di nị dà dà na, chỉ đa ca lệ ta bà ha. (3 lần)"]],"p":"Phần Dịch Nghĩa"},{"t":"Kệ Niệm Phật","b":[["v",["A Di Đà Phật thân sắc vàng,","Tướng tốt rực rỡ, hào quang sáng ngời,","Mày trắng tỏa, Tu Di uyển chuyển,","Mắt trong ngần, bốn biển long lanh,","Ánh hào quang hóa vô số Phật,","Vô số Bồ Tát hiện ở trong,","Bốn mươi tám nguyện độ chúng sanh,","Chín phẩm sen vàng lên giải thoát.","Quy mạng lễ A Di Đà Phật,","Ở Phương Tây thế giới an lành,","Con nay xin phát nguyện vãng sanh,","Cúi xin Đức Từ Bi Tiếp độ.","Nam Mô Tây Phương Cực Lạc Thế Giới","Đại Từ Đại Bi A Di Đà Phật."]],["v",["Nam mô A Di Đà Phật. (21 lần)","Nam mô Đại Bi Quán Thế Âm Bồ Tát. (3 lần)","Nam mô Đại Thế Chí Bồ Tát. (3 lần)","Nam mô Địa Tạng Vương Bồ Tát. (3 lần)","Nam mô Thanh Tịnh Đại Hải Chúng Bồ","Tát. (3 lần)"]]],"p":"Phần Dịch Nghĩa"},{"t":"Sám Thập Phương","b":[["v",["Ba đời mười phương Phật,","A Di Đà bậc nhất,","Chín phẩm độ chúng sanh,","Oai đức không cùng cực,","Con nay nguyện quy y,","Sám hối ba nghiệp tội,","Phàm được bao phước thiện,","Chí tâm nguyện hồi hướng,","Nguyện cùng người niệm Phật,","Vãng sanh nước Cực Lạc,","Thấy Phật ngộ pháp tánh,","Phát tâm đại Bồ đề,","Đoạn vô biên phiền não,","Tu vô lượng pháp môn,","Thệ nguyện độ chúng sanh,","Đều trọn thành Phật đạo."]]],"p":"Phần Dịch Nghĩa"},{"t":"Phúng Kinh","b":[["v",["Phúng kinh công đức thù thắng hạnh,","Vô biên thắng phước giai hồi hướng,","Phổ nguyện pháp giới chư chúng sanh,","Tốc vãng vô lượng quang Phật sát."]],["v",["Nguyện tiêu tam chướng trừ phiền não,","Nguyện đắc trí huệ chơn minh liễu,","Phổ nguyện tội chướng tất tiêu trừ,","Thế thế thường hành Bồ tát đạo."]],["v",["Nguyện sanh Tây Phương Tịnh Độ trung,","Cửu phẩm Liên hoa vi phụ mẫu,","Hoa khai kiến Phật ngộ vô sanh,","Bất thối Bồ tát vi bạn lữ."]],["v",["Nguyện dĩ thử công đức,","Phổ cập ư nhất thiết,","Ngã đẳng dữ chúng sanh,","Giai cộng thành Phật đạo."]]],"p":"Phần Dịch Nghĩa"},{"t":"Tam Quy Y","b":[["p","Tự quy y Phật, đương nguyện chúng sanh, thể giai đại đạo, phát vô thượng tâm."],["p","Tự quy y Pháp, đương nguyện chúng sanh, thâm nhập kinh tạng, trí huệ như hải."],["p","Tự quy y Tăng, đương nguyện chúng sanh, thống lý đại chúng, nhất thiết vô ngại."]],"p":"Phần Dịch Nghĩa"},{"t":"Hồi Hướng","b":[["v",["Nguyện đem công đức nầy,","Hướng về khắp tất cả,","Đệ tử và chúng sanh,","Đều trọn thành phật đạo."]],["v",["NIỆM HƯƠNG","(Thắp đèn đốt hương trầm xong, đứng ngay ngắn chắp tay"]],["v",["để ngang ngực mật niệm.)","TỊNH PHÁP GIỚI CHƠN NGÔN","Án lam tóa ha. (3 lần)","TỊNH TAM NGHIỆP CHƠN NGÔN"]],["v",["Án ta phạ bà phạ, thuật đà ta phạ, đạt mạ","ta phạ, bà phạ thuật độ hám. (3 lần)"]],["p","(Chủ lễ thắp ba cây hương quỳ ngay thẳng cầm hương"],["p","ngang trán niệm bài cúng hương.)"]],"p":"Phần Dịch Nghĩa"},{"t":"Cúng Hương","b":[["v",["Nguyện thử diệu hương vân","Biến mãn thập phương giới","Cúng dường nhất thiết Phật","Tôn pháp chư Bồ Tát","Vô biên Thanh Văn chúng","Cập nhất thiết Thánh Hiền","Duyên khởi quang minh đài","Xứng tánh tác Phật sự","Phổ huân chư chúng sanh","Giai phát Bồ Đề tâm","Viễn ly chư vọng nghiệp","Viên thành vô thượng đạo."]]],"p":"Phần Dịch Âm"},{"t":"Tán Phật","b":[["v",["Pháp vương vô thượng tôn","Tam giới vô luân thất","Thiên nhơn chi Đạo sư","Tứ sanh chi từ phụ","Ư nhất niệm quy y","Năng diệt tam kỳ nghiệp","Xưng dương nhược tán thán","Ức kiếp mạc năng tận."]]],"p":"Phần Dịch Âm"},{"t":"Quán Tưởng","b":[["v",["Năng lễ, sở lễ tánh không tịch,","Cảm ứng đạo giao nan tư nghì,","Ngã thử đạo tràng như đế châu,","Thập phương chư Phật ảnh hiện trung,","Ngã thân ảnh hiện chư Phật tiền,","Đầu diện tiếp túc quy mạng lễ."]]],"p":"Phần Dịch Âm"},{"t":"Đảnh Lễ","b":[["p","Chí tâm đảnh lễ: Nam mô tận hư không, biến pháp giới, quá, hiện, vị lai thập phương chư Phật, Tôn Pháp, Hiền Thánh Tăng, Thường Trú Tam Bảo. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Ta Bà Giáo Chủ Bổn Sư Thích Ca Mâu Ni Phật, Đương Lai Hạ Sanh Di Lặc Tôn Phật, Đại Trí Văn Thù Sư Lợi Bồ Tát, Đại Hạnh Phổ Hiền Bồ Tát, Hộ Pháp Chư Tôn Bồ Tát, Linh Sơn Hội Thượng Phật Bồ Tát. (1 lạy)"],["p","Chí tâm đảnh lễ: Nam mô Tây Phương Cực Lạc Thế Giới Đại Từ Đại Bi A Di Đà Phật, Đại Bi Quán Thế Âm Bồ Tát, Đại Thế Chí Bồ Tát, Đại Nguyện Địa Tạng Vương Bồ Tát, Thanh Tịnh Đại Hải Chúng Bồ Tát. (1 lạy)"]],"p":"Phần Dịch Âm"},{"t":"Tán Lư Hương","b":[["v",["Lư hương sạ nhiệt","Pháp giới mông huân","Chư Phật hải hội tất diêu văn","Tùy xứ kiết tường vân","Thành ý phương ân","Chư Phật hiện toàn thân."]],["p","Nam mô Hương Vân Cái Bồ Tát. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Chú Đại Bi","b":[["v",["Nam mô Đại Bi Hội Thượng Phật Bồ Tát. (3 lần)","Thiên thủ thiên nhãn vô ngại đại bi tâm đà la ni.","Nam mô hắc ra đát na, đa ra dạ da."]],["p","Nam mô a rị da, bà lô yết đế, thước bát ra da, Bồ đề tát đỏa bà da, ma ha tát đỏa bà da, ma ha ca lô ni ca da. Án, tát bàn ra phạt duệ số đát na đát tỏa."],["p","Nam mô tất kiết lật đỏa y mông a rị da, bà lô kiết đế thất Phật ra lăng đà bà."],["p","Nam mô na ra cẩn trì hê rị, ma ha bàn đa sa mế, tát bà a tha đậu du bằng, a thệ dựng, tát bà tát đa, na ma bà già, ma phạt đạt đậu, đát điệt tha. Án a bà lô hê, lô ca đế, ca ra đế, di hê rị, ma ha bồ đề tát đỏa, tát bà tát bà, ma ra ma ra, ma hê ma hê, rị đà dựng, câu lô câu lô kiết mông, độ lô độ lô, phạt xà da đế, ma ha phạt xà da đế, đà ra đà ra, địa rị ni, thất Phật ra da, dá ra dá ra. Mạ mạ phạt ma ra, mục đế lệ, y hê y hê, thất na thất na a ra sâm Phật ra xá lợi, phạt sa phạt sâm, Phật ra xá da, hô lô hô lô ma ra, hô lô hô lô hê rị, ta ra ta ra, tất rị tất rị, tô rô tô rô, bồ đề dạ bồ đề dạ, bồ đà dạ, bồ đà dạ, di đế rị dạ, na ra cẩn trì địa rị sắc ni na, ba dạ ma na ta bà ha."],["p","Tất đà dạ ta bà ha. Ma ha tất đà dạ ta bà ha. Tất đà du nghệ thất bàn ra dạ ta bà ha."],["p","Na ra cẩn trì ta bà ha. Ma ra na ra ta bà ha. Tất ra tăng a mục khê da, ta bà ha. Ta bà ma ha, a tất đà dạ, ta bà ha. Giả kiết ra a tất đà dạ, ta bà ha. Ba đà ma yết tất đà dạ, ta bà ha. Na ra cẩn trì bàn đà ra dạ, ta bà ha. Ma bà lị thắng yết ra dạ, ta bà ha."],["v",["Nam mô hắc ra đát na, đa ra dạ da.","Nam mô a rị da, bà lô yết đế thước bàng ra dạ, ta bà ha.","Án tất điện đô, mạn đa ra, bạt đà dạ, ta bà ha. (3 lần)"]]],"p":"Phần Dịch Âm"},{"t":"Phát Nguyện Văn","b":[["p","Nam Mô Thập Phương Thường Trụ Tam"],["p","Bảo. (3 lần)"],["v",["Khể thủ tam giới Tôn","Quy mạng thập phương Phật","Ngã kim phát hoằng nguyện","Trì thử Di Đà kinh","Thượng báo tứ trọng ân","Hạ tế tam đồ khổ","Nhược hữu kiến văn giả","Tất phát bồ đề tâm","Tận thử nhất báo thân","Vãng sanh Cực Lạc quốc."]],["p","Nam Mô Bổn Sư Thích Ca Mâu Ni Phật. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Khai Kinh","b":[["v",["Vô thượng thậm thâm vi diệu pháp","Bá thiên vạn kiếp nan tao ngộ","Ngã kim kiến văn đắc thọ trì","Nguyện giải Như Lai chân thật nghĩa."]],["p","Nam Mô Liên Trì Hải Hội Phật Bồ Tát. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Phật Thuyết A Di Đà Kinh","b":[["p","(Đời Diêu Tần ngài Tam Tạng Pháp Sư Cưu Ma La Thập"],["p","vưng chiếu dịch.)"],["p","Như thị ngã văn: Nhất thời Phật tại Xá vệ quốc, Kỳ thọ Cấp Cô Độc viên, dữ đại tỳ kheo tăng, thiên nhị bách ngũ thập nhơn câu, giai thị đại A La Hán, chúng sở tri thức: Trưởng lão Xá Lợi Phất, Ma ha Mục Kiền Liên, Ma ha Ca Diếp, Ma ha Ca Chiên Diên, Ma ha Câu Hy La, Ly Bà Đa, Châu Lợi Bàn Đà Dà, Nan Đà, A Nan Đà, La Hầu La, Kiều Phạm Ba Đề, Tân Đầu Lô Phả La Đọa, Ca Lưu Đà Di, Ma ha Kiếp Tân Na, Bạc Câu La, A Nậu Lâu Đà, như thị đẳng chư đại đệ tử. Tinh chư Bồ tát Ma ha tát: Văn Thù Sư Lợi pháp vương tử, A Dật Đa Bồ Tát, Càn Đà Ha Đề Bồ Tát, Thường Tinh Tấn Bồ Tát, dữ như thị đẳng chư đại Bồ Tát, Cập Thích Đề Hoàn Nhơn đẳng, vô lượng chư thiên đại chúng câu."],["p","Nhĩ thời Phật cáo Trưởng lão Xá Lợi Phất: Tùng thị Tây phương quá thập vạn ức Phật độ, hữu thế giới danh viết Cực Lạc, kỳ độ hữu Phật hiệu A Di Đà, kim hiện tại thuyết pháp."],["p","Xá Lợi Phất! Bỉ độ hà cố danh vi Cực lạc? Kỳ quốc chúng sanh vô hữu chúng khổ, đản thọ chư lạc, cố danh Cực Lạc."],["p","Hựu Xá Lợi Phất! Cực Lạc quốc độ, thất trùng lan thuẫn, thất trùng la võng, thất trùng hàng thọ, giai thị tứ bảo, châu tráp vi nhiễu, thị cố bỉ quốc, danh vi Cực Lạc."],["p","Hựu Xá Lợi Phất! Cực Lạc quốc độ, hữu thất bảo trì, bát công đức thủy, sung mãn kỳ trung. Trì để thuần dĩ kim sa bố địa, tứ biên giai đạo, kim ngân, lưu ly, pha lê hiệp thành, thượng hữu lâu các, diệc dĩ kim ngân, lưu ly, pha lê, xa cừ, xích châu, mã não, nhi nghiêm sức chi; trì trung liên hoa, đại như xa luân, thanh sắc thanh quang, huỳnh sắc huỳnh quang, xích sắc xích quang, bạch sắc, bạch quang, vi diệu hương khiết."],["p","Xá Lợi Phất! Cực Lạc quốc độ, thành tựu như thị công đức trang nghiêm."],["p","Hựu Xá Lợi Phất! Bỉ Phật quốc độ, thường tác thiên nhạc, huỳnh kim vi địa, trú dạ lục thời, vũ thiên mạn đà la hoa, kỳ độ chúng sanh, thường dĩ thanh đán, các dĩ y kích, thạnh chúng diệu hoa, cúng dường tha phương, thập vạn ức Phật. Tức dĩ thực thời, hoàn đáo bổn quốc, phạn thực kinh hành."],["p","Xá Lợi Phất! Cực Lạc quốc độ thành tựu như thị công đức trang nghiêm."],["p","Phục thứ, Xá Lợi Phất! Bỉ quốc thường hữu chủng chủng kỳ diệu tạp sắc chi điểu: bạch hạc, khổng tước, anh võ, xá lợi, ca lăng tần già, cộng mạng chi điểu."],["p","Thị chư chúng điểu, trú dạ lục thời, xuất hòa nhã âm. Kỳ âm diễn xướng, Ngũ Căn, Ngũ Lực, Thất Bồ Đề Phần, Bát Thánh Đạo Phần, như thị đẳng pháp. Kỳ độ chúng sanh, văn thị âm dĩ, giai tất niệm Phật, niệm Pháp, niệm Tăng."],["p","Xá Lợi Phất! Nhữ vật vị thử điểu thiệt thị tội báo sở sanh. Sở dĩ giả hà? Bỉ Phật quốc độ, vô tam ác đạo."],["p","Xá Lợi Phất! Kỳ Phật quốc độ, thượng vô ác đạo chi danh, hà huống hữu thiệt. Thị chư chúng điểu giai thị A Di Đà Phật, dục linh pháp âm tuyên lưu, biến hóa sở tác."],["p","Xá Lợi Phất! Bỉ Phật quốc độ, vi phong suy động, chư bảo hàng thọ, cập bảo la võng, xuất vi diệu âm, thí như bá thiên chủng nhạc, đồng thời câu tác. Văn thị âm giả, tự nhiên giai sanh niệm Phật, niệm Pháp, niệm Tăng chi tâm."],["p","Xá Lợi Phất! Kỳ phật quốc độ, thành tựu như thị công đức trang nghiêm."],["p","Xá Lợi Phất! Ư nhữ ý vân hà? Bỉ Phật hà cố hiệu A Di Đà?"],["p","Xá Lợi Phất! Bỉ Phật quang minh vô lượng, chiếu thập phương quốc, vô sở chướng ngại, thị cố hiệu vi A Di Đà."],["p","Hựu Xá Lợi Phất! Bỉ Phật thọ mạng, cập kỳ nhơn dân, vô lượng, vô biên a tăng kỳ kiếp, cố danh A Di Đà."],["p","Xá Lợi Phất! A Di Đà Phật thành Phật dĩ lai, ư kim thập kiếp."],["p","Hựu Xá Lợi Phất! Bỉ Phật hữu vô lượng vô biên Thanh văn đệ tử, giai A La Hán, phi thị toán số chi sở năng tri. Chư Bồ Tát chúng, diệc phục như thị."],["p","Xá Lợi Phất! Bỉ Phật quốc độ, thành tựu như thị công đức trang nghiêm."],["p","Hựu Xá Lợi Phất! Cực Lạc quốc độ, chúng sanh sanh giả, giai thị A Bệ Bạt Trí, kỳ trung đa hữu nhất sanh bổ xứ. Kỳ số thậm đa, phi thị toán số, sở năng tri chi, đản khả dĩ vô lượng vô biên a tăng kỳ thuyết."],["p","Xá Lợi Phất! Chúng sanh văn giả, ưng đương phát nguyện, nguyện sanh bỉ quốc. Sở dĩ giả hà? Đắc dữ như thị chư thượng thiện nhơn, câu hội nhất xứ."],["p","Xá Lợi Phất! Bất khả dĩ thiểu thiện căn phước đức nhơn duyên đắc sanh bỉ quốc."],["p","Xá Lợi Phất! Nhược hữu thiện nam tử, thiện nữ nhơn, văn thuyết A Di Đà Phật, chấp trì danh hiệu, nhược nhất nhật, nhược nhị nhật, nhược tam nhật, nhược tứ nhật, nhược ngũ nhật, nhược lục nhật, nhược thất nhật, nhất tâm bất loạn, kỳ nhơn lâm mạng chung thời, A Di Đà Phật dữ chư Thánh chúng, hiện tại kỳ tiền. Thị nhơn chung thời, tâm bất điên đảo, tức đắc vãng sanh A Di Đà Phật Cực Lạc quốc độ."],["p","Xá Lợi Phất! Ngã kiến thị lợi, cố thuyết thử ngôn. Nhược hữu chúng sanh văn thị thuyết giả, ưng đương phát nguyện, sanh bỉ quốc độ."],["p","Xá Lợi Phất! Như ngã kim giả, tán thán A Di Đà Phật, bất khả tư nghị công đức chi lợi."],["p","Đông phương diệc hữu A Súc Bệ Phật, Tu Di Tướng Phật, Đại Tu Di Phật, Tu Di Quang Phật, Diệu Âm Phật, như thị đẳng hằng hà sa số chư Phật, các ư kỳ quốc, xuất quảng trường thiệt tướng, biến phú tam thiên đại thiên thế giới, thuyết thành thiệt ngôn: nhữ đẳng chúng sanh đương tín thị “xưng tán bất khả tư nghị công đức, nhất thiết chư Phật, sở hộ niệm kinh”."],["p","Xá Lợi Phất! Nam phương thế giới hữu Nhật Nguyệt Đăng Phật, Danh Văn Quang Phật, Đại Diệm Kiên Phật, Tu Di Đăng Phật, Vô Lượng Tinh Tấn Phật, như thị đẳng hằng hà sa số chư Phật các ư kỳ quốc, xuất quảng trường thiệt tướng, biến phú tam thiên đại thiên thế giới, thuyết thành thiệt ngôn: nhữ đẳng chúng sanh đương tín thị “xưng tán bất khả tư nghị công đức, nhất thiết chư Phật sở hộ niệm kinh”."],["p","Xá Lợi Phất! Tây phương thế giới hữu Vô Lượng Thọ Phật, Vô Lượng Tướng Phật, Vô Lượng Tràng Phật, Đại Quang Phật, Đại Minh Phật, Bảo Tướng Phật, Tịnh Quang Phật, như thị đẳng hằng hà sa số chư Phật, các ư kỳ quốc, xuất quảng trường thiệt tướng, biến phú tam thiên đại thiên thế giới, thuyết thành thiệt ngôn: nhữ đẳng chúng sanh đương tín thị “xưng tán bất khả tư nghị công đức, nhất thiết chư Phật, sở hộ niệm kinh”."],["p","Xá Lợi Phất! Bắc phương thế giới hữu Diệm Kiên Phật, Tối Thắng Âm Phật, Nan Trở Phật, Nhựt Sanh Phật, Võng Minh Phật, như thị đẳng hằng hà sa số chư Phật, các ư kỳ quốc, xuất quảng trường thiệt tướng, biến phú tam thiên đại thiên thế giới, thuyết thành thiệt ngôn: nhữ đẳng chúng sanh đương tín thị “xưng tán bất khả tư nghị công đức, nhất thiết chư Phật, sở hộ niệm kinh”."],["p","Xá Lợi Phất! Hạ phương thế giới, hữu Sư Tử Phật, Danh Văn Phật, Danh Quang Phật, Đạt Ma Phật, Pháp Tràng Phật, Trì Pháp Phật, như thị đẳng hằng hà sa số chư Phật, các ư kỳ quốc, xuất quảng trường thiệt tướng biến phú tam thiên đại thiên thế giới, thuyết thành thiệt ngôn: nhữ đẳng chúng sanh đương tín thị “xưng tán bất khả tư nghị công đức, nhất thiết chư Phật sở hộ niệm kinh”."],["p","Xá Lợi Phất! Thượng phương thế giới hữu Phạm Âm Phật, Tú Vương Phật, Hương Thượng Phật, Hương Quang Phật, Đại Diệm Kiên Phật, Tạp Sắc Bảo Hoa Nghiêm Thân Phật, Ta La Thọ Vương Phật, Bảo Hoa Đức Phật, Kiến Nhất Thiết Nghĩa Phật, Như Tu Di Sơn Phật, Như thị đẳng hằng hà sa số chư Phật, các ư kỳ quốc, xuất quảng trường thiệt tướng, biến phú tam thiên đại thiên thế giới, thuyết thành thiệt ngôn: nhữ đẳng chúng sanh đương tín thị “xưng tán bất khả tư nghị công đức, nhất thiết chư Phật sở hộ niệm kinh”."],["p","Xá lợi Phất! Ư nhữ ý vân hà? Hà cố danh vi “nhất thiết chư Phật, sở hộ niệm kinh?”"],["p","Xá lợi Phất! Nhược hữu thiện nam tử, thiện nữ nhơn, văn thị kinh, thọ trì giả, cập văn chư Phật danh giả, thị chư thiện nam tử, thiện nữ nhơn giai vi nhất thiết chư Phật chi sở hộ niệm, giai đắc bất thối chuyển ư A Nậu Đa La Tam Miệu Tam Bồ Đề."],["p","Thị cố Xá Lợi Phất! Nhữ đẳng giai đương tín thọ ngã ngữ, cập chư Phật sở thuyết."],["p","Xá Lợi Phất! Nhược hữu nhơn dĩ phát nguyện, kim phát nguyện, đương phát nguyện, dục sanh A Di Đà Phật quốc giả, thị chư nhơn đẳng giai đắc bất thối chuyển ư A Nậu Đa La Tam Miệu Tam Bồ Đề, ư bỉ quốc độ, nhược dĩ sanh, nhược kim sanh, nhược đương sanh."],["p","Thị cố Xá lợi Phất! Chư thiện nam tử, thiện nữ nhơn, nhược hữu tín giả, ưng đương phát nguyện, sanh bỉ quốc độ."],["p","Xá lợi Phất! Như ngã kim giả, xưng tán chư Phật bất khả tư nghị công đức; bỉ chư Phật đẳng diệc xưng tán ngã bất khả tư nghị công đức, nhi tác thị ngôn: “Thích Ca Mâu Ni Phật, năng vi thậm nan hy hữu chi sự, năng ư Ta Bà quốc độ, ngũ trược ác thế: kiếp trược, kiến trược, phiền não trược, chúng sanh trược, mạng trược trung, đắc A Nậu Đa La Tam Miệu Tam Bồ Đề, vị chư chúng sanh, thuyết thị nhất thiết thế gian nan tín chi pháp.”"],["p","Xá lợi Phất! Đương tri ngã ư ngũ trược ác thế, hành thử nan sự, đắc A Nậu Đa La Tam Miệu Tam Bồ Đề, vị nhất thiết thế gian, thuyết thử nan tín chi pháp, thị vi thậm nan."],["p","Phật thuyết thử kinh dĩ, Xá Lợi Phất, cập chư Tỳ kheo, nhất thiết thế gian, Thiên, Nhơn, A Tu La đẳng, văn Phật sở thuyết, hoan hỷ tín thọ, tác lễ nhi khứ."],["p","Phật thuyết A Di Đà kinh."]],"p":"Phần Dịch Âm"},{"t":"Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh","b":[["p","Quán Tự Tại Bồ Tát hành thâm Bát Nhã Ba La Mật Đa thời, chiếu kiến ngũ uẩn giai không độ nhất thiết khổ ách."],["p","Xá Lợi Tử! Sắc bất dị không, không bất dị sắc, sắc tức thị không, không tức thị sắc, thọ, tưởng, hành, thức diệc phục như thị."],["p","Xá Lợi Tử! Thị chư pháp không tướng, bất sanh, bất diệt, bất cấu, bất tịnh, bất tăng, bất giảm. Thị cố không trung vô sắc, vô thọ, tưởng, hành, thức, vô nhãn, nhĩ, tỷ, thiệt, thân, ý, vô sắc, thinh, hương, vị, xúc, pháp, vô nhãn giới, nãi chí vô ý thức giới, vô vô minh diệc vô vô minh tận, nãi chí vô lão tử diệc, vô lão tử tận, vô khổ, tập, diệt, đạo, vô trí diệc vô đắc. Dĩ vô sở đắc cố, Bồ đề tát đỏa y Bát Nhã Ba La Mật Đa cố, tâm vô quái ngại, vô quái ngại cố, vô hữu khủng bố, viễn ly điên đảo mộng tưởng cứu cánh Niết Bàn. Tam thế chư Phật y Bát Nhã Ba La Mật Đa cố, đắc a nậu đa la tam miệu tam bồ đề. Cố tri Bát Nhã Ba La Mật Đa, thị đại thần chú, thị đại minh chú, thị vô thượng chú, thị vô đẳng đẳng chú, năng trừ nhất thiết khổ, chơn thật bất hư."],["v",["Cố thuyết Bát Nhã Ba La Mật Đa chú.","Tức thuyết chú viết:"]],["p","“Yết đế yết đế, ba la yết đế, ba la tăng yết đế, bồ đề tát bà ha.” (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Vãng Sanh Quyết Định Chơn Ngôn","b":[["p","Nam mô a di đa bà dạ, đa tha già đa dạ, đa địa dạ tha. A di rị đô bà tỳ, a di rị đa tất đam bà tỳ, a di rị đa tỳ ca lan đế, a di rị đa tỳ ca lan đa, dà di nị dà dà na, chỉ đa ca lệ ta bà ha. (3 lần)"]],"p":"Phần Dịch Âm"},{"t":"Di Đà Tán","b":[["v",["Tây phương giáo chủ","Tịnh Độ năng nhân","Tứ thập bát nguyện độ chúng sanh","Phát nguyện thệ hoằng thâm","Thượng phẩm thượng sanh","Đồng nguyện bảo liên thành."]]],"p":"Phần Dịch Âm"},{"t":"Đảnh Lễ","b":[["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Vô Lượng Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Vô Biên Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Vô Ngại Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Vô Đối Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Diệm Vương Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Thanh Tịnh Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Hoan Hỷ Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Trí Tuệ Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Nan Tư Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Bất Đoạn Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Vô Xưng Quang Như Lai. (1 lạy)"],["p","Nam mô An Dưỡng Quốc Cực Lạc Giới Di Đà Hải Hội Siêu Nhật Nguyệt Quang Như Lai. (1 lạy)"]],"p":"Phần Dịch Âm"},{"t":"Sám Thập Phương","b":[["v",["Thập phương tam thế Phật,","A Di Đà đệ nhất,","Cửu phẩm độ chúng sanh,","Oai đức vô cùng cực,","Ngã kim đại quy y,","Sám hối tam nghiệp tội,","Phàm hữu chư phước thiện,","Chí tâm dụng hồi hướng,","Nguyện đồng niệm Phật nhân,","Cảm ứng tùy thời hiện,","Lâm chung Tây Phương cảnh,","Phân minh tại mục tiền,","Kiến văn giai tinh tấn,","Đồng sanh Cực Lạc quốc,","Kiến Phật liễu sanh tử,","Như Phật độ nhất thiết,","Vô biên phiền não đoạn,","Vô lượng pháp môn tu,","Thệ nguyện độ chúng sanh,","Tổng nguyện thành Phật đạo,","Hư không hữu tận, ngã nguyện vô cùng,","Tình dữ vô tình, đồng viên chủng trí."]]],"p":"Phần Dịch Âm"},{"t":"Phúng Kinh","b":[["v",["Phúng kinh công đức thù thắng hạnh,","Vô biên thắng phước giai hồi hướng,","Phổ nguyện pháp giới chư chúng sanh,","Tốc vãng vô lượng quang Phật sát."]],["v",["Nguyện tiêu tam chướng trừ phiền não,","Nguyện đắc trí huệ chơn minh liễu,","Phổ nguyện tội chướng tất tiêu trừ,","Thế thế thường hành Bồ tát đạo."]],["v",["Nguyện sanh Tây Phương Tịnh Độ trung,","Cửu phẩm Liên hoa vi phụ mẫu,","Hoa khai kiến Phật ngộ vô sanh,","Bất thối Bồ tát vi bạn lữ."]],["v",["Nguyện dĩ thử công đức,","Phổ cập ư nhất thiết,","Ngã đẳng dữ chúng sanh,","Giai cộng thành Phật đạo."]]],"p":"Phần Dịch Âm"},{"t":"Tam Quy Y","b":[["p","Tự quy y Phật, đương nguyện chúng sanh, thể giai đại đạo, phát vô thượng tâm."],["p","Tự quy y Pháp, đương nguyện chúng sanh, thâm nhập kinh tạng, trí huệ như hải."],["p","Tự quy y Tăng, đương nguyện chúng sanh, thống lý đại chúng, nhất thiết vô ngại."]],"p":"Phần Dịch Âm"},{"t":"Hồi Hướng","b":[["v",["Nguyện đem công đức nầy,","Hướng về khắp tất cả,","Đệ tử và chúng sanh,","Đều trọn thành phật đạo."]]],"p":"Phần Dịch Âm"},{"t":"Incense Praise","b":[["v",["Incense in the censer now is burning;","all the dharma realm receives the"]],["v",["fragrance.","From afar the sea vast host of buddhas all"]],["v",["inhale its sweetness.","In every place auspicious clouds"]],["v",["appearing, our sincere intention thus fulfilling,","as all buddhas now show their perfect","body.","Namo Incense Cloud Canopy Bodhisattva,","Mahasattva. (3 times)"]]],"p":"Phần Dịch Tiếng Anh"},{"t":"Sutra Declaration","b":[["p","The unsurpassed, profound, and"],["p","wonderful Dharma, is diffci ult to encounter in hundreds of"],["v",["millions of eons.","I now see and hear it, receive and uphold"]],["v",["it, and I vow to fathom the Tathagata’s true","meaning.","Namo Fundamental Teacher Shakyamuni","Buddha. (3 times)"]]],"p":"Phần Dịch Tiếng Anh"},{"t":"The Buddha Speaks Of Amitabha Sutra","b":[["v",["(Translated by Tripitaka Master Kumarajiva of Yao Ch’in.","English translation by the Buddhist Text Translation","Society, Burlingame, California, USA.)"]],["p","Thus I have heard. At one time the Buddha dwelt at Sravasti, in the Jeta Grove, in the Garden of the Benefactor of Orphans and the Solitary, together with a gathering of great Bhikshus, twelve hundred ffi ty in all, all great Arhats whom the assembly knew and recognized. Elders Shariputra, Mahamaudgalyayana, Mahakasyapa, Mahakatyayana, Mahakausthila, Revata, Suddhipanthaka, Nanda, Ananda, Rahula, Gavampati, Pindola Bharadvaja, Kalodayin, Mahakapphina, Vakkula, Aniruddha, and others such as these, all great disciples; together with all the Bodhisattvas, Mahasattvas: Dharma Prince Manjushri, Ajita Bodhisattva, Gandhahastin Bodhisattva, Nityodyukta Bodhisattva, and others such as these, all great Bodhisattvas, and together with Shakra, chief among gods, and the numberless great multitudes from all the heavens."],["p","At that time the Buddha told the elder Sariputra: “passing from here through hundreds of thousands of millions of Buddhalands to the west, there is a world called Ultimate Bliss. In this land, a Buddha called Amitabha right now teaches the dharma."],["p","“Sariputra, for what reason is this land called Ultimate Bliss?"],["p","“All living beings of this country endure none of the sufferings, but enjoy every bliss. Therefore it is called Ultimate Bliss."],["p","“Moreover, Sariputra, this Land of Ultimate Bliss is everywhere surrounded by seven tiers of railings, seven layers of netting, and seven rows of trees, all formed from the four treasures and for this reason named Ultimate Bliss."],["p","“Moreover, Sariputra, this Land of Ultimate Bliss has pools of the seven jewels, fli led with the waters of eight meritorious virtues. The bottom of each pool is pure, spread over with golden sand. On the four sides are stairs of gold, silver, lapis lazuli, and crystal, above are raised pavilions adorned with gold, silver, lapis lazuli, crystal, mother-of-pearl, red pearls, and carnelian."],["p","“In the pools are lotuses as large as carriage wheels, green coloured of green light, yellow coloured of yellow light, red coloured of red light, white coloured of white light, subtly, wonderfully, fragrant and pure."],["p","“Sariputra, the realisation of the Land of Ultimate Bliss is thus meritoriously adorned."],["p","“Moreover, Sariputra, in that Buddhaland there is always heavenly music and the ground is yellow gold. In the six periods of the day and night a heavenly rain of mandarava fol wers falls, and throughout the clear morning, each living being of that land, with sacks full of the myriads of wonderful fol wers, makes offerings to the hundreds of thousands of millions of Buddhas of the other directions. At mealtime, they return to their own country, and having eaten, they stroll around."],["p","“Sariputra, the realisation of the Land of Ultimate Bliss is thus meritoriously adorned."],["p","“Moreover Sariputra, in this country there are always rare and wonderful vari-coloured birds; white geese, The Principle Proper peacocks, parrots, and egret, kalavinkas, and two-headed birds."],["p","In the six periods of the day and night the fol cks of birds sing forth harmonious and elegant sounds; their clear and joyful sounds proclaim The Five Roots, The Five Powers, The Seven Bodhi Shares, The Eight Sagely Way Shares, and dharmas such as these. When living beings of this land hear these sounds, they are altogether mindful of the Buddha, mindful of the dharma, and mindful of the sangha."],["p","“Sariputra, do not say that these birds are born as retribution for their karmic offences. For what reason? In this Buddhaland there are no Three Evil Ways of rebirth. Sariputra, in this Buddhaland not even the names of the Three Evil Ways exist, how much the less their actuality! Desiring that the dharma-sound be widely proclaimed, Amitabha Buddha by transformation made this multitude of birds."],["p","“Sariputra, in that Buddhaland when the soft wind blows, the rows of jewelled trees and jewelled nets give forth The Principle Proper subtle and wonderful sounds, like one hundred thousand kinds of music played at the same time. All those who hear these sounds naturally bring forth in their hearts mindfulness of the Buddha, mindfulness of the dharma, and mindfulness of the sangha."],["p","“Sariputra, the realisation of the Land of Ultimate Bliss is thus meritoriously adorned."],["p","“Sariputra, what do you think? Why is this Buddha called Amitabha?"],["p","Sariputra, the brilliance of that Buddha’s light is measureless, illuminating the lands of the ten directions everywhere without obstruction, for this reason he is called Amitabha."],["p","“Moreover, Sariputra, the life of that Buddha and that of his people extends for measureless, limitless asamkhyeya kalpas; for this reason he is called amitayus. And Sariputra, since Amitabha realised Buddhahood ten kalpas have passed."],["p","“Moreover, Sariputra, that Buddha has measureless, limitless ‘sound-hearer’ disciples, all arhats, their number incalculable; thus also is the assembly of Bodhisattvas."],["p","“Sariputra, the realisation of the Land of Ultimate Bliss is thus meritoriously adorned."],["p","“Moreover, Sariputra, those living beings born in the land of the Ultimate Bliss are all avaivartika. Among them are many who in this very life will dwell in Buddhahood. Their number is extremely many; it is incalculable and only in measureless, limitless asamkhyeya kalpas could it be spoken."],["p","“Sariputra, those living beings who hear should vow: ‘I wish to be born in that country.’ and why? Those who thus attain are all superior and good people, all gathered together in one place."],["p","Sariputra, one cannot have few good roots, blessings, virtues, and causal connections to attain birth in that land."],["p","“Sariputra, if there is a good man or a good woman who hears spoken ‘Amitabha’ and holds the name, whether for one day, two days, three days, four days, fvi e days, six days, as long as seven days, with one heart unconfused, when this person approaches the end of life, before him will appear Amitabha and all the assembly of holy ones. When the end comes, his heart is without inversion. In Amitabha’s Land of Ultimate Bliss he will attain rebirth. Sariputra, because I see this benefti\u0001 I speak these words. If living beings hear this spoken they should make the vow: ‘I will be born in that land.’"],["p","“Sariputra, as I now praise the inconceivable benefti from the merit and virtue of Amitabha, thus in the east are also Aksobhya Buddha, Sumeru Appearance Buddha, Great Sumeru Buddha, Sumeru Light Buddha, Wonderful Sound Buddha, all Buddhas such as these, numberless as ganges sands. In his own country each brings forth the appearance of a vast and long tongue, everywhere covering the three thousand great thousand worlds, and speaks the sincere and actual words: ‘All you living beings should believe, praise, and hold in reverence the inconceivable merit and virtue of this sutra of the mindful one of whom all Buddhas are protective.’"],["p","“Sariputra, in the southern world are Sun Moon Lamp Buddha, Well-Known Light Buddha, Great Blazing Shoulders Buddha, Sumeru Lamp Buddha, Measureless Vigour Buddha, all Buddhas such as these, numberless as ganges sands. In his own country each brings forth the appearance of a vast and long tongue, everywhere covering the three thousand great thousand worlds, and speaks the sincere and actual words: ‘All you living beings should believe, praise, and hold in reverence the inconceivable merit and virtue of this sutra of the mindful one of whom all Buddhas are protective.’"],["p","“Sariputra, in the western world are Measureless Life Buddha, Measureless Appearance Buddha, Measureless Curtain Buddha, Great Light Buddha, Great Brightness Buddha, Jewelled Appearance Buddha, Pure Light Buddha, all Buddhas such as these, numberless as ganges sands. In his own country each brings forth the appearance of a vast and long tongue, everywhere covering the three thousand great thousand worlds, and speaks the sincere and actual words: ‘All you living beings should believe, praise, and hold in reverence the inconceivable merit and virtue of this sutra of the mindful one of whom all Buddhas are protective.’"],["p","“Sariputra, in the northern world are Blazing Shoulders Buddha, Most Victorious Sound Buddha, Hard to Injure Buddha, Sun Birth Buddha, Net Brightness Buddha, all Buddhas such as these, numberless as ganges sands. In his own country each brings forth the appearance of a vast and long tongue, everywhere covering the three thousand great thousand worlds, and speaks the sincere and actual words: ‘All you living beings should believe, praise, and hold in reverence the inconceivable merit and virtue of this sutra of the mindful one of whom all Buddhas are protective.’"],["p","“Sariputra, in the world below are Lion Buddha, Well Known Buddha, Famous Light Buddha, Dharma Buddha, Dharma Curtain Buddha, Dharma Maintaining Buddha, all Buddhas such as these, numberless as ganges sands. In his own country each brings forth the appearance of a vast and long tongue, everywhere covering the three thousand great thousand worlds, and speaks the sincere and actual words: ‘All you living beings should believe, praise, and hold in reverence the inconceivable merit and virtue of this sutra of the mindful one of whom all Buddhas are protective.’"],["p","“Sariputra, in the world above are Pure Sound Buddha, King of Past Lives Buddha, Superior Fragrance Buddha, Fragrant Light Buddha, Great Blazing Shoulders Buddha, Vari-Coloured Jewels And Flower Adornment Body Buddha, Sala Tree King Buddha, Jewelled Flower Virtue Buddha, Vision of All Meaning Buddha, Such As Mount Sumeru Buddha, all Buddhas such as these, numberless as ganges sands. In his own country each brings forth the appearance of a vast and long tongue, everywhere covering the three thousand great thousand worlds and speaks the sincere and actual words: ‘All you living beings should believe, praise, and hold in reverence the inconceivable merit and virtue of this sutra of the mindful one of whom all Buddhas are protective.’"],["p","“Sariputra, what do you think? Why is it called ‘sutra of the mindful one of whom all Buddhas are protective?’ Sariputra, if a good man or good woman hears this sutra and holds to it, and hears the names of all these Buddhas, this good man or woman will be the mindful one of whom all Buddhas are protective, and will irreversibly attain to anuttara samyak sambodhi. Therefore, Sariputra, all of you should believe and accept my words and those which all Buddhas speak."],["p","“Sariputra, if there are people who have already made the vow, who now make the vow, or who are about to make the vow: ‘I desire to be born in Amitabha’s country,’ these people, whether born in the past, now being born, or to be born in the future, all will irreversibly attain to anuttara samyak sambodhi. Therefore, Sariputra, all good men and good women, if they are among those who have faith, should make the vow: ‘I will be born in that country.’"],["p","“Sariputra, just as I now praise the inconceivable merit and virtue of all Buddhas, all those Buddhas equally praise my inconceivable merit and virtue saying these words: ‘Sakyamuni Buddha can complete extremely rare and difficult deeds. In the saha land, in the evil time of The Five Turbidities: In the Midst of the Kalpa Turbidity, The View Turbidity, The Affil ction Turbidity, The Living Beings Turbidity, and the Life Turbidity, he can attain anuttara samyak sambodhi and for the sake of living beings, speak this dharma which in the whole world is hard to believe.’"],["p","“Sariputra, you should know that I, in the evil time of The Five Turbidities, practice these diffci ult deeds, attain anuttara samyak sambodhi, and for all the world speak this dharma, diffci ult to believe, extremely diffci ult!”"],["p","After the Buddha spoke this sutra, Sariputra and all the bhiksus, all the gods, men, and asuras, and others from all the worlds, hearing what the Buddha had said, joyously welcomed, faithfully accepted, bowed and withdrew."],["p","End of The Buddha Speaks of Amitabha Sutra."]],"p":"Phần Dịch Tiếng Anh"},{"t":"The Four Great Vows","b":[["v",["I vow to save the limitless living beings.","I vow to cut off the inexhaustible"]],["v",["afflictions.","I vow to study the immeasurable"]],["v",["Dharma-doors.","I vow to realize the supreme Buddha"]],["p","Way."]],"p":"Phần Dịch Tiếng Anh"},{"t":"The Three Refuges","b":[["v",["To the buddha I return and rely,","vowing that all living beings","understand the great way profoundly,","and bring forth the bodhi mind."]],["v",["To the dharma I return and rely,","vowing that all living beings","deeply enter the sutra treasury,","and have wisdom like the sea."]],["v",["To the sangha I return and rely,","vowing that all living beings","form together a great assembly","one and all in harmony."]]],"p":"Phần Dịch Tiếng Anh"},{"t":"Dedication Of Merits","b":[["p","I vow to transfer these merits, all of which I have attained, to all sentient beings. May I and all sentient beings realize together the path to Buddhahood."]],"p":"Phần Dịch Tiếng Anh"}]};
